function readAdd(add)
  t=gg.getValues({[1]={address=add,flags=4}})
  add=string.format("%X",t[1].value)
  if (#add)==16 then add=add:sub(9,16) end
  if (#add)==1 then add=add.."0000000" else
    add=string.format("%d","0x"..add)
  end
  return add
end
