function nc_offset(addr, tablex, tt)
  for i, v in ipairs(tablex) do
    if v[4] == true then
      gg.addListItems({{address = addr + v[3], flags = v[2], value = v[1], freeze = v[4]}})
     else
      gg.setValues({{address = addr + v[3], flags = v[2], value = v[1]}})
    end
  end
  gg.toast((tt or "") .. "开启成功")
end
function getso(So_name)
  return gg.getRangesList(So_name)[1].start
end

function BaAdd(add)
  t = gg.getValues({[1] = {address = add, flags = 4}})
  return t[1].value & 0xFFFFFFFF
end
function readPointer(Add, Item)
  for i = 1, (#Item - 1) do
    Add = BaAdd(Add + Item[i])
  end
  return Add + Item[#Item]
end
function setvalue(add, value, falgs, dj)
  local WY = {}
  WY[1] = {}
  WY[1].address = add
  WY[1].value = value
  WY[1].flags = falgs
  if dj == true then
    WY[1].freeze = true
    gg.addListItems(WY)
   else
    gg.setValues(WY)
  end
end
function getnc(Name, nc)
  local t = gg.getRangesList(Name)
  for i, v in ipairs(t) do
    if v.state == nc then
      return v.start
    end
  end
end

function SearchWrite(Search, Write, Type)
  gg.clearResults()
  gg.setVisible(false)
  gg.searchNumber(Search[1][1], Type)
  local count = gg.getResultCount()
  local result = gg.getResults(count)
  gg.clearResults()
  local data = {}
  local base = Search[1][2]

  if (count > 0) then
    for i, v in ipairs(result) do
      v.isUseful = true
    end

    for k = 2, #Search do
      local tmp = {}
      local offset = Search[k][2] - base
      local num = Search[k][1]

      for i, v in ipairs(result) do
        tmp[#tmp + 1] = {}
        tmp[#tmp].address = v.address + offset
        tmp[#tmp].flags = v.flags
      end

      tmp = gg.getValues(tmp)

      for i, v in ipairs(tmp) do
        if (tostring(v.value) ~= tostring(num)) then
          result[i].isUseful = false
        end
      end
    end
    for i, v in ipairs(result) do
      if (v.isUseful) then
        data[#data + 1] = v.address
      end
    end

    if (#data > 0) then
      gg.toast("\n共修改" .. #data .. "条数据")
      local t = {}
      local base = Search[1][2]
      for i = 1, #data do
        for k, w in ipairs(Write) do
          offset = w[2] - base
          t[#t + 1] = {}
          t[#t].address = data[i] + offset
          t[#t].flags = Type
          t[#t].value = w[1]

          if (w[3] == true) then
            local item = {}
            item[#item + 1] = t[#t]
            item[#item].freeze = true
            gg.addListItems(item)
          end

        end
      end
      gg.setValues(t)
     else
      gg.toast("\n开启失败", false)
      return false
    end
   else
    gg.toast("\n开启失败")
    return false
  end
end
