g=gg.getValues({[1]={address=ttt,flags=16,value=9}})
gg.addListItems({[1]={address=ttt,flags=16,value=9}})

if g[1].value>0.7 then
local t = Base_address({"libunity.so:bss", "Cb", 1})
local tt = {0x34990, 0x1874, 0xE5C}
local ttt = Get_address(t, tt)
gg.setValues({[1]={address=ttt,flags=16,value=9}})
else
local t = Base_address({"libunity.so:bss", "Cb", 1})
local tt = {0x34990, 0x1874, 0xE5C}
local ttt = Get_address(t, tt)
g=gg.setValues({[1]={address=ttt,flags=16,value=-10}})
end
gg.toast("自动判断高度".."\n如果高度超过0.7那么修改穿墙")
end

end

