function ic1()
local g=os.clock()
gg.clearResults()
gg.setRanges(gg.REGION_ANONYMOUS)
	 gg.searchNumber("2F;30F::5", FLOAT, false, gg.SIGN_EQUAL, 0, -1)
	 gg.searchNumber("2", FLOAT, false, gg.SIGN_EQUAL, 0, -1)
	 gg.getResults(100)
	 gg.editAll("999", FLOAT)
 gg.clearResults()
	 gg.toast("修改成功")
end

