function jg1()
     gg.clearResults()
	 gg.setRanges(32)
	 gg.searchNumber("3.58732407e-43;1.0;0.0;0.5;0.30000001192;7.5;0.60000002384::", gg.TYPE_FLOAT, false, gg.SIGN_EQUAL, 0, -1)
	 gg.searchNumber("0", gg.TYPE_FLOAT, false, gg.SIGN_EQUAL, 0, -1)
	 jg=gg.getResults(100)
	 sl=gg.getResultCount()
	 if sl>100 then sl=100 end
	 for i = 1, sl do
	 	 dzy=jg[i].address
	 	 gg.addListItems({[1] = {address = dzy,flags = gg.TYPE_FLOAT,freeze = true,value = 0}})
	 end
	 gg.toast("星辰圣女攻击无间隔开启成功")
	 gg.clearResults()
     end
     
 
 
